-- Rifts World Book 36: Sovietski - body armor, printed 212-216.
-- 9 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~381-sovietski-armor.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
--
-- ALL 9 ARE NEW: no gear row in production cites Rifts World Book 36 as armor,
-- and no slug here was held (q.mjs --remote, 2026-11-22).
--
-- THE SEVEN MODELS ARE NINE ROWS. SA-110 Red Nova prints three grades
-- (HMA, HMB, HMC) with their own M.D.C., weight and price, so it is three
-- rows, the way Warlords of Russia's Cyborg Battle Armor is.
--
-- SA-109LMM IS NOT THE HELD WB17 ROW. sovietski-red-star-medium-body-armor
-- (Warlords of Russia p.173) is an 18 lb, 75 M.D.C. human suit; SA-109LMM is
-- an 80 lb, 170 M.D.C. Light Machine suit. A new row; the held one is left as
-- it is.
--
-- mdc STORES THE MAIN BODY; the other locations are in the description.
-- A cost printed as "70,000+" stores the stated figure. Every M.D.C. block,
-- weight and price was read off a 150 dpi render of printed 212-216, not the
-- cache. SA-301EBA's Class line reads SA-113HBA; the heading's model number
-- names the row.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('sovietski-sa-107h-red-star-infantry-armor', 'SA-107H Red Star "Human" Infantry Body Armor', 'rifts', 'armor', 18, 35000, '35,000 credits on the Black Market. Rare: impersonating a Sovietski soldier carries the death penalty, and theft of state property means years of hard labor or death.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 65, 'Standard-issue Red Star armor for the Sovietski''s human soldiers and police, and for lightly augmented partial cyborgs. Red and black, with composite plates over chest, belly, shoulders, forearms and shins, flexible M.D.C. padding under the black outer garment elsewhere, and spikes after the rays of the red star (+1D6 S.D.C. to a head butt or shoulder block from a human wearer). Non-environmental: an open-face helmet with a light-adjusting M.D.C. visor, a gas mask that clips to the helmet, and back connectors for a backpack or jet pack. Helmet-mounted short-range radio, 10 miles (16 km). M.D.C.: main body 65, helmet 50, each arm 22, each leg 32. Good mobility: -10% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets.', 'Rifts World Book 36: Sovietski p.212-213', NULL),
  ('sovietski-sa-108lml-red-star-light-machine-light-armor', 'SA-108LML Red Star "Light Machine" Light Body Armor', 'rifts', 'armor', 50, 70000, '70,000+ credits on the Black Market; the stated figure is stored. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 130, 'The Red Star suit cut for Light Machine cyborgs: it looks like the infantry armor, but its composite is heavier and it carries more M.D.C. Non-environmental, with the same helmet radio (10 miles/16 km) and light-adjusting polarized visor. The spikes add +1D4 M.D. to a Light Machine''s head butt or shoulder block. M.D.C.: main body 130, helmet 50, each arm 35, each leg 45. Mobility good to excellent: no penalty for a Light Machine; a partial cyborg 55-80% bionic is at -10% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets.', 'Rifts World Book 36: Sovietski p.213', NULL),
  ('sovietski-sa-109lmm-red-star-light-machine-medium-armor', 'SA-109LMM Red Star "Light Machine" Medium Body Armor', 'rifts', 'armor', 80, 95000, '95,000+ credits on the Black Market; the stated figure is stored. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 170, 'The heaviest of the three Red Star suits, built for Light Machine cyborgs; same look and features as the lighter suits (helmet radio, polarized visor, spikes adding +1D4 M.D. to a Light Machine''s head butt). Not the WB17 Red Star Medium Body Armor, which is an 18-pound, 75 M.D.C. human suit. M.D.C.: main body 170, helmet 50, each arm 45, each leg 60. Mobility excellent for a Light Machine, -5% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets. Too bulky for a partial cyborg: one who wears it is at -30% on those skills, -20% speed, -2 initiative, and -1 to strike, parry, dodge, roll, disarm and pull punch.', 'Rifts World Book 36: Sovietski p.213-214', NULL),
  ('sovietski-sa-110hma-red-nova-light-heavy-machine-armor', 'SA-110HMA Red Nova Light Heavy Machine Body Armor', 'rifts', 'armor', 150, 95000, '95,000 credits on the Black Market. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 150, 'Lightest grade of the Red Nova, the Red Star''s bigger, bulkier cousin for 8-9 foot Heavy Machine full-conversion cyborgs, in the same red and black. Full helmet with a removable face plate, which may be worn without the plate or left off. Forearm and upper-leg plates slide aside so built-in weapons, tools and leg compartments can be reached. Helmet radio (10 miles/16 km) and polarized visor. Spikes add +1D6 M.D. to a Heavy Machine''s head butt or shoulder block. Non-environmental. M.D.C.: main body 150, helmet 50, each arm 45, each leg 60. No mobility penalty.', 'Rifts World Book 36: Sovietski p.214', NULL),
  ('sovietski-sa-110hmb-red-nova-medium-heavy-machine-armor', 'SA-110HMB Red Nova Medium Heavy Machine Body Armor', 'rifts', 'armor', 200, 160000, '160,000 credits on the Black Market. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 200, 'Middle grade of the Red Nova armor for Heavy Machine cyborgs; it looks almost identical to the light and heavy grades, differing in helmet detail and trim. Full helmet with a removable face plate, sliding forearm and upper-leg plates for built-in weapons and compartments, helmet radio (10 miles/16 km), polarized visor, spikes adding +1D6 M.D. to a Heavy Machine''s head butt. Non-environmental. M.D.C.: main body 200, helmet 60, each arm 55, each leg 80. -10% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets.', 'Rifts World Book 36: Sovietski p.214', NULL),
  ('sovietski-sa-110hmc-red-nova-heavy-heavy-machine-armor', 'SA-110HMC Red Nova Heavy Heavy Machine Body Armor', 'rifts', 'armor', 260, 220000, '220,000 credits on the Black Market. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 250, 'Heaviest grade of the Red Nova armor for Heavy Machine cyborgs, a walking bulldozer in red and black. Full helmet with a removable face plate, sliding forearm and upper-leg plates for built-in weapons and compartments, helmet radio (10 miles/16 km), polarized visor, spikes adding +1D6 M.D. to a Heavy Machine''s head butt. Non-environmental. M.D.C.: main body 250, helmet 80, each arm 60, each leg 100. -15% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets.', 'Rifts World Book 36: Sovietski p.214', NULL),
  ('sovietski-ssa-213-shooting-star-exoskeleton-armor', 'Spetsnaz SSA-213 Shooting Star Rapid Strike Exoskeleton Armor', 'rifts', 'armor', 30, 385000, '385,000+ credits on the Black Market; the stated figure is stored. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', '2D6+5 S.D.C. restrained punch, 1 M.D. full punch, 1D6 M.D. power punch (two attacks), 1D4 M.D. kick, 2D4 M.D. leap kick (two attacks)', 1, NULL, NULL, NULL, NULL, NULL, 120, 'Exoskeleton-assisted armor for Spetsnaz commandos, special forces and agents, styled apart from the Red Star and slim enough to hide under a long coat. Black with red, silver or gold trim for the Spetsnaz; gun-metal gray, snow white, green or camouflage for Special Forces. Jet pack connectors on the back, helmet radio (10 miles/16 km), polarized visor. Non-environmental. The frame gives a robot P.S. 20 (carry up to 400 lbs/180 kg for 15 minutes at -20% speed), +1 P.P., +20% speed, leaps of 10 ft (3 m) up and 15 ft (4.6 m) across (+50% running), half the usual fatigue, +5% to Swimming, S.C.U.B.A. and Climbing/Rappelling. It lets the wearer use Light Machine weapons without penalty, Heavy Machine weapons at half penalty, and two-handed human weapons in one hand. M.D.C.: main body 120, helmet 50, each arm 45, each leg 60. Excellent mobility: no penalty for humans or partial cyborgs 60% bionic or more.', 'Rifts World Book 36: Sovietski p.214-215', NULL),
  ('sovietski-ssa-213h-black-star-body-armor', 'Spetsnaz SSA-213H Black Star "Human" Body Armor', 'rifts', 'armor', 18, 60000, '60,000 credits on the Black Market. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 70, 'Light armor in the Shooting Star''s styling with no exoskeleton or augmentation at all. In black it is the Spetsnaz''s everyday regalia, often seen under a coat or cloak; in silver with black accents and a white star it is Silver Star armor, worn by Red Star Reservists, police trainees and some senior government and Party officials. Issued only to authorized humans, partial cyborgs and Light Machines. Helmet radio (10 miles/16 km) and polarized visor. M.D.C.: main body 70, helmet 50, each arm 25, each leg 35. Good mobility: -10% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets.', 'Rifts World Book 36: Sovietski p.215-216', NULL),
  ('sovietski-sa-301eba-proletariat-body-armor', 'SA-301EBA Proletariat Full Environmental Body Armor', 'rifts', 'armor', 18, 80000, '80,000 credits on the Black Market. Rare, for the same death penalty and hard-labor reasons as all Sovietski armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 100, 'The Armiya Sovietski''s newest suit, and its only fully sealed one, for humans, partial cyborgs and Light Machines (its Class line reads SA-113HBA). Standard environmental features: sealed against water, gas, smoke and dust to a depth of 250 ft (76 m); computer-run life support with cooling, air circulation, filtering and a five-hour oxygen supply; heat shielding to 200 C (392 F), so ordinary fire does nothing while nuclear, plasma, magical and M.D. fire hit in full; minimal radiation shielding; tinted polarized visor with HUD; helmet radio (10 miles/16 km); a face plate that comes off with the helmet on; back clamps for a jet pack, backpack or ammo drum. Forearm and upper-leg plates slide aside for a cyborg''s built-in weapons and compartments. M.D.C.: main body 100, helmet 60, each arm 35, each leg 55. Humans -15% to physical skills such as Prowl, Swimming, Climbing, Acrobatics and Pick Pockets; partial cyborgs -5%; Light Machines no penalty.', 'Rifts World Book 36: Sovietski p.216', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 9 gear rows are in' AS assertion, count(*) AS got, 9 AS want
  FROM gear WHERE slug IN ('sovietski-sa-107h-red-star-infantry-armor', 'sovietski-sa-108lml-red-star-light-machine-light-armor', 'sovietski-sa-109lmm-red-star-light-machine-medium-armor', 'sovietski-sa-110hma-red-nova-light-heavy-machine-armor', 'sovietski-sa-110hmb-red-nova-medium-heavy-machine-armor', 'sovietski-sa-110hmc-red-nova-heavy-heavy-machine-armor', 'sovietski-ssa-213-shooting-star-exoskeleton-armor', 'sovietski-ssa-213h-black-star-body-armor', 'sovietski-sa-301eba-proletariat-body-armor') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~381-sovietski-armor.sql');
